using System;
using UnityEngine;

namespace FPS
{
    /// <summary>
    /// Imported (Asset Store) character models a soldier can wear instead of the procedural body.
    /// Lives in Resources/CharacterModels.asset, generated by Tools > FPS > Build Character Models.
    /// Index 0 of CharacterLook.model is the procedural soldier; model i uses entries[i - 1].
    /// </summary>
    [CreateAssetMenu(menuName = "FPS/Character Model DB")]
    public class CharacterModelDB : ScriptableObject
    {
        [Serializable]
        public class Entry
        {
            public string name;
            public GameObject prefab;
            /// <summary>Optional: replaces every material of the model (texture skins of one mesh).</summary>
            public Material skin;
        }

        public Entry[] entries = new Entry[0];

        static CharacterModelDB instance;
        static bool loaded;

        public static CharacterModelDB Instance
        {
            get
            {
                if (!loaded) { instance = Resources.Load<CharacterModelDB>("CharacterModels"); loaded = true; }
                return instance;
            }
        }

        public static int Count => Instance ? Instance.entries.Length : 0;

        /// <summary>Entry for CharacterLook.model (null for 0 / procedural or out of range).</summary>
        public static Entry Get(int model)
        {
            var db = Instance;
            if (!db || model <= 0 || model > db.entries.Length) return null;
            var e = db.entries[model - 1];
            return e != null && e.prefab ? e : null;
        }
    }
}
